using i128 = __int128_t;
using ull = unsigned long long;

int dp[20][2][2];   
char dig[20];       
ull memo_cnt[20][2][2];
i128 memo_sum[20][2][2];
int len;

string tostr(i128 x){
    if(x == 0) return "0";
    bool neg = x < 0;
    if(neg) x = -x;
    string s;
    while(x > 0){
        int d = (int)(x % 10);
        s.push_back('0' + d);
        x /= 10;
    }
    if(neg) s.push_back('-');
    reverse(s.begin(), s.end());
    return s;
}

pair<ull, i128> recur(int i, bool tight, bool nonzero) {
    if(i == 0){

        return {1ULL, (i128)0};
    }
    int it = dp[i][tight?1:0][nonzero?1:0];
    if(it == 1){
        return { memo_cnt[i][tight?1:0][nonzero?1:0], memo_sum[i][tight?1:0][nonzero?1:0] };
    }
    int lim = tight ? (int)dig[i] : 9;
    ull total_cnt = 0;
    i128 total_sum = 0;
    for(int d = 0; d <= lim; ++d){
        bool nonzero2 = nonzero || (d != 0);
        bool tight2 = tight && (d == lim);
        auto child = recur(i - 1, tight2, nonzero2);
        ull cnt = child.first;
        i128 sumc = child.second;
        if(nonzero2){

            total_sum += sumc + (i128)cnt;
        } else {
            total_sum += sumc;
        }
        total_cnt += cnt;
    }
    dp[i][tight?1:0][nonzero?1:0] = 1;
    memo_cnt[i][tight?1:0][nonzero?1:0] = total_cnt;
    memo_sum[i][tight?1:0][nonzero?1:0] = total_sum;
    return { total_cnt, total_sum };
}

int main() {
    unsigned long long n;
    cin >> n;
    if(n == 0){
        cout << 0 << "\n";
        return 0;
    }
    int ind = 1;
    while(n > 0) {
        dig[ind++] = (char)(n % 10);
        n /= 10;
    }
    len = ind - 1; 

    for(int i = 0; i < 20; ++i)
        for(int a = 0; a < 2; ++a)
            for(int b = 0; b < 2; ++b)
                dp[i][a][b] = -1;
    auto ans = recur(len, true, false);

    cout << tostr(ans.second) << "\n";
}